using System.Collections.Generic;public class Solution{TreeNode F(List<int>a,int l,int r){if(l>r)return null;int m=(l+r)/2;return new TreeNode(a[m],F(a,l,m-1),F(a,m+1,r));}public TreeNode SortedListToBST(ListNode h){var a=new List<int>();for(;h!=null;h=h.next)a.Add(h.val);return F(a,0,a.Count-1);}}
